import firstDeck from "./generated/ship-main.json";
import grandLobby from "./generated/grand-lobby.json";
import personalCabin from "./generated/personal-cabin.json";
import swimmingPool from "./generated/swimming-pool.json";
import secretDeck from "./generated/secret-deck.json";
import secondDeck from "./generated/second-deck.json";
import type { WalkableMap } from "../systems/walkability";

/**
 * Every place on the ship. Generated by scripts/build-ship-assets.ts — edit
 * the layouts in scripts/maps/, never the JSON by hand.
 */
export const MAPS = {
  "ship-main": firstDeck as WalkableMap,
  "grand-lobby": grandLobby as WalkableMap,
  "personal-cabin": personalCabin as WalkableMap,
  "swimming-pool": swimmingPool as WalkableMap,
  "secret-deck": secretDeck as WalkableMap,
  "second-deck": secondDeck as WalkableMap,
} as const;

export type MapId = keyof typeof MAPS;
export const MAP_IDS = Object.keys(MAPS) as MapId[];

/** First Deck: where new passengers board and the default location. */
export const SHIP_MAP = MAPS["ship-main"];
export const DEFAULT_MAP_ID: MapId = "ship-main";

export function isMapId(id: unknown): id is MapId {
  return typeof id === "string" && Object.hasOwn(MAPS, id);
}

export function getMap(id: string): WalkableMap | null {
  return isMapId(id) ? MAPS[id] : null;
}

export const ASSET_BASE = "/game";
